head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};
scwin.onpageload = function() {
	window.showAlertCal13 = false;
};
scwin.inputCalendar13_ondateselect = function(dateStr, dateObj) {
	if (dateStr) {
		inputCalendar13.disableBeforeDate(dateStr);
	}
};
scwin.inputCalendar14_ondateselect = function(dateStr, dateObj) {
	if (dateStr) {
		inputCalendar14.disableAfterDate(dateStr);
	}
};
scwin.trigger1_onclick = function(e) {
	inputCalendar13.enableAllDate();
	showAlertCal13 = true;
};
scwin.__isBeforeDisabled = function() {
	var count = 0;
	var el = ((j) => j.length ? j : $('#mf_inputCalendar13_calendar_cell_2_2'))($('#inputCalendar13_calendar_cell_2_2')).prevAll();
	var length = el.length;
	el.each(function() {
		if (scwin.__getJq(this).hasClass("w2calendar_date_disable")) {
			count++;
		}
	});
	((j) => j.length ? j : $('#mf_inputCalendar13_calendar_cell_2_2'))($('#inputCalendar13_calendar_cell_2_2')).parent().prevAll().each(function() {
		scwin.__getJq(this).find("td").each(function() {
			if (scwin.__getJq(this).hasClass("w2calendar_date_disable")) {
				count++;
			}
			length++;
		});
	});
	return length == count;
};
scwin.__isAfterDisabled = function() {
	var count = 0;
	var el = ((j) => j.length ? j : $('#mf_inputCalendar14_calendar_cell_2_2'))($('#inputCalendar14_calendar_cell_2_2')).nextAll();
	var length = el.length;
	el.each(function() {
		if (scwin.__getJq(this).hasClass("w2calendar_date_disable")) {
			count++;
		}
	});
	((j) => j.length ? j : $('#mf_inputCalendar14_calendar_cell_2_2'))($('#inputCalendar14_calendar_cell_2_2')).parent().nextAll().each(function() {
		scwin.__getJq(this).find("td").each(function() {
			if (scwin.__getJq(this).hasClass("w2calendar_date_disable")) {
				count++;
			}
			length++;
		});
	});
	return length == count;
};
